using System.Net;using System.Net.Sockets;using System.Text;using System.Text.Json;namespace TVOS;public sealed class RemoteServer:IDisposable{readonly TcpListener l;readonly CancellationTokenSource stop=new();readonly AppSettings set;readonly ServiceManager sm;readonly Action<string> launch;readonly Action home;public RemoteServer(AppSettings s,ServiceManager m,Action<string>a,Action h){set=s;sm=m;launch=a;home=h;l=new(IPAddress.Any,s.RemotePort);}public void Start(){l.Start();_=Task.Run(Loop);}public string Url(){var ip=Dns.GetHostEntry(Dns.GetHostName()).AddressList.FirstOrDefault(x=>x.AddressFamily==AddressFamily.InterNetwork&&!IPAddress.IsLoopback(x));return $"http://{ip??IPAddress.Loopback}:{set.RemotePort}/remote/?token={set.RemoteToken}";}async Task Loop(){while(!stop.IsCancellationRequested)try{var c=await l.AcceptTcpClientAsync(stop.Token);_=Task.Run(()=>Handle(c));}catch{}}async Task Handle(TcpClient c){using(c)using var s=c.GetStream();using var r=new StreamReader(s,Encoding.UTF8,false,8192,true);var q=await r.ReadLineAsync();if(q==null)return;var p=q.Split(' ');var headers=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);string? x;while(!string.IsNullOrEmpty(x=await r.ReadLineAsync())){var i=x.IndexOf(':');if(i>0)headers[x[..i]]=x[(i+1)..].Trim();}var n=headers.TryGetValue("Content-Length",out var z)&&int.TryParse(z,out var nn)?nn:0;var body="";if(n>0){var b=new char[n];var got=0;while(got<n){var k=await r.ReadAsync(b,got,n-got);if(k==0)break;got+=k;}body=new(b,0,got);}var u=new Uri("http://x"+p[1]);var token=Query(u.Query).GetValueOrDefault("token","");if(u.AbsolutePath.StartsWith("/api/")&&token!=set.RemoteToken){await Reply(s,403,"text/plain","Forbidden");return;}if(p[0]=="GET"&&u.AbsolutePath.StartsWith("/remote")){var rel=u.AbsolutePath is "/remote" or "/remote/"?"index.html":u.AbsolutePath[8..];var f=Path.GetFullPath(Path.Combine(AppPaths.Remote,rel));if(!f.StartsWith(Path.GetFullPath(AppPaths.Remote))||!File.Exists(f)){await Reply(s,404,"text/plain","Not found");return;}await ReplyBytes(s,200,Mime(f),await File.ReadAllBytesAsync(f));return;}if(p[0]=="GET"&&u.AbsolutePath=="/api/state"){await Reply(s,200,"application/json",JsonSerializer.Serialize(new{services=sm.Load().Services,theme=ThemeManager.Resolve(set.Theme)}));return;}if(p[0]=="POST"&&u.AbsolutePath=="/api/action"){using var d=JsonDocument.Parse(body);var a=d.RootElement.GetProperty("action").GetString();switch(a){case"home":home();break;case"up":InputManager.Key(0x26);break;case"down":InputManager.Key(0x28);break;case"left":InputManager.Key(0x25);break;case"right":InputManager.Key(0x27);break;case"ok":InputManager.Key(0x0D);break;case"back":InputManager.Key(0xA6);break;case"playpause":InputManager.Key(0xB3);break;case"sleep":PowerManager.Sleep();break;case"text":if(d.RootElement.TryGetProperty("text",out var t))InputManager.Text(t.GetString()??"");break;case"launch":if(d.RootElement.TryGetProperty("url",out var v))launch(v.GetString()??"");break;}await Reply(s,200,"application/json","{\"ok\":true}");return;}if(p[0]=="POST"&&u.AbsolutePath=="/api/services"){var cfg=JsonSerializer.Deserialize<ServicesConfig>(body,new JsonSerializerOptions{PropertyNameCaseInsensitive=true});if(cfg==null){await Reply(s,400,"text/plain","Bad request");return;}for(int i=0;i<cfg.Services.Count;i++){cfg.Services[i].Order=i;if(string.IsNullOrWhiteSpace(cfg.Services[i].Id))cfg.Services[i].Id=Guid.NewGuid().ToString("N")[..10];}sm.Save(cfg);await Reply(s,200,"application/json","{\"ok\":true}");return;}await Reply(s,404,"text/plain","Not found");}static Dictionary<string,string> Query(string q)=>q.TrimStart('?').Split('&',StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Split('=',2)).ToDictionary(x=>Uri.UnescapeDataString(x[0]),x=>x.Length>1?Uri.UnescapeDataString(x[1]):"");static string Mime(string f)=>Path.GetExtension(f).ToLowerInvariant()switch{".html"=>"text/html; charset=utf-8",".css"=>"text/css",".js"=>"text/javascript",".svg"=>"image/svg+xml",_=>"application/octet-stream"};static Task Reply(NetworkStream s,int c,string t,string b)=>ReplyBytes(s,c,t,Encoding.UTF8.GetBytes(b));static async Task ReplyBytes(NetworkStream s,int c,string t,byte[] b){var h=Encoding.ASCII.GetBytes($"HTTP/1.1 {c} OK\r\nContent-Type: {t}\r\nContent-Length: {b.Length}\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n");await s.WriteAsync(h);await s.WriteAsync(b);}public void Dispose(){stop.Cancel();l.Stop();}}